import "server-only";
import type { Tree } from "@/lib/engine/types";
import maxHarrow from "./max-harrow-skyfall-4p.json";
import theoMarsh from "./theo-marsh-skyfall-2p.json";

// Every mystery is a story tree generated by the murder-mystery-story-tree skill and validated
// by its validate_tree.py. Imported server-only: trees hold the killer and every clue's target.
// ponytail: a static list; move to a `mysteries` table if they ever need adding without a deploy.

const TWO_CANOPIES = `\
   .-''''-.
  /||||||||\\        ~~~
  \\||||||||/         |
   \\||||||/          |
     \\||/            o
      o             /|\\
     /|\\            / \\
     / \\`;

const FOUR_CANOPIES = `\
  .--.      .--.
 /||||\\    /||||\\
  \\||/      \\||/
   o         o
         .--.     ~~~
  .--.  /||||\\     |
 /||||\\  \\||/      o
  \\||/    o
   o`;

export type Mystery = { slug: string; setting: string; art: string; tree: Tree };

export const MYSTERIES: Mystery[] = [
  { slug: "theo-marsh-skyfall-2p", setting: "Skyfall", art: TWO_CANOPIES, tree: theoMarsh as unknown as Tree },
  { slug: "max-harrow-skyfall-4p", setting: "Skyfall", art: FOUR_CANOPIES, tree: maxHarrow as unknown as Tree },
];

export function getMystery(slug: string): Mystery | undefined {
  return MYSTERIES.find((m) => m.slug === slug);
}

/** Public card data for the case picker. No killer, no clues. */
export type MysteryCard = {
  slug: string;
  setting: string;
  art: string;
  title: string;
  victim: string;
  difficulty: string;
  playerCount: number;
};

export function mysteryCards(): MysteryCard[] {
  return MYSTERIES.map(({ slug, setting, art, tree }) => ({
    slug,
    setting,
    art,
    title: tree.meta.title,
    victim: tree.meta.victim.name,
    difficulty: tree.meta.difficulty,
    playerCount: tree.meta.player_count,
  }));
}
